// Daftar file Target Control per bulan. TAMBAH BULAN BARU: tambahkan 1 baris 'YYYY-MM': '<id file Google Sheet>',
// lalu bagikan file itu (Viewer) ke service account n8n. Tab yang dibaca: CONTROL DASHBOARD, blok CHANNEL MARKETING (B6:G14).
const FILES = {
  '2026-07': '1PVm_RMx_zzM-g6frS9jQcSMLJuJ5jFRbs-ECid791lQ',
  '2026-08': '1g367ggwGkiy84iOcsPRg2qlvzEsufb5XS7O38Fu-G9M',
  '2026-09': '1_m7Q0s3tuqpAv2esxbYeyvBhRAMdc9A-s674VBn4lhk',
  '2026-10': '1UoznzWqXZtCuSJZEbB7QKxombEumuKK80yCO1YZGGAQ',
  '2026-11': '1wnfe5MmUnVKwdk4OLdGJOt8sHyRlCJlELEpvkK7DBBM',
};
const q = ($('Webhook Channel').first().json.query) || {};
const now = DateTime.now().setZone('Asia/Makassar');
const tahun = /^\d{4}$/.test(String(q.tahun || '')) ? String(q.tahun) : String(now.year);
const list = Object.keys(FILES).sort().filter(b => b.startsWith(tahun + '-') && FILES[b]);
if (!list.length) return [{ json: { bulan: null, tahun, file: 'TIDAK-ADA', kosong: true } }];
return list.map(bulan => ({ json: { bulan, tahun, file: FILES[bulan] } }));

// Satu putaran loop = satu file/bulan. Bungkus semua baris CONTROL DASHBOARD file ini jadi 1 item {bulan, file, rows|error}.
// (Versi 1 memetakan baris ke bulan lewat pairedItem → node Sheets hanya membaca file pertama & baris ke-i jatuh ke bulan ke-i. Sekarang tidak dipakai.)
const f = $('Loop Bulan').first().json;
if (f.kosong) return [{ json: f }];
const its = $input.all(), err = its.find(i => i.json && i.json.error);
const rows = its.map(i => i.json).filter(j => j && Object.keys(j).length);
return [{ json: { bulan: f.bulan, tahun: f.tahun, file: f.file, error: err ? String(err.json.error.message || err.json.error) : (rows.length ? undefined : 'tab CONTROL DASHBOARD kosong / tidak terbaca'), rows: err ? [] : rows } }];

// Susun respons: per bulan → channel {target, realisasi, achieve, kontribusi, selisih} dari CONTROL DASHBOARD (angka apa adanya dari sheet).
function susun(files, rowsPerFile, tahun, sekarang) {
  const num = v => { if (v === null || v === undefined || v === '') return null; if (typeof v === 'number') return v;
    const s = String(v).replace(/[^0-9,.\-%]/g, ''); if (!s) return null; const pct = s.endsWith('%'); let x = s.replace('%', '');
    if (/,\d{1,2}$/.test(x)) x = x.replace(/\./g, '').replace(',', '.'); else x = x.replace(/[.,](?=\d{3}(\D|$))/g, '');
    const n = parseFloat(x); return isFinite(n) ? (pct ? n / 100 : n) : null; };
  const kunci = (row, re) => Object.keys(row).find(k => re.test(String(k).toUpperCase()));
  const bulan = files.map((f, i) => {
    const rows = rowsPerFile[i];
    if (!rows || rows.error) return { bulan: f.bulan, file: f.file, ok: false, error: rows && rows.error ? String(rows.error) : 'tidak terbaca' };
    const r0 = rows[0] || {};
    const kC = kunci(r0, /CHANNEL/) || Object.keys(r0)[0], kT = kunci(r0, /TARGET/), kR = kunci(r0, /REALISASI/), kA = kunci(r0, /ACHIEVE/), kK = kunci(r0, /KONTRIBUSI/), kS = kunci(r0, /SELISIH/);
    if (!kT || !kR) return { bulan: f.bulan, file: f.file, ok: false, error: 'kolom TARGET PER-CHANNEL / REALISASI tidak ditemukan di CONTROL DASHBOARD B6:G14' };
    const channel = [];
    for (const r of rows) {
      const c = String(r[kC] ?? '').trim().toUpperCase().replace(/\s+/g, ' ');
      if (!c || /^UNIT BISNIS/.test(c)) { if (channel.length) break; else continue; }
      const t = num(r[kT]) || 0, re = num(r[kR]) || 0;
      channel.push({ channel: c, target: t, realisasi: re, achieve: kA ? num(r[kA]) : (t ? re / t : null), kontribusi: kK ? num(r[kK]) : null, selisih: kS ? num(r[kS]) : re - t });
    }
    return { bulan: f.bulan, file: f.file, ok: channel.length > 0, error: channel.length ? undefined : 'baris channel kosong',
      target: channel.reduce((a, c) => a + c.target, 0), realisasi: channel.reduce((a, c) => a + c.realisasi, 0), channel };
  });
  return { ok: bulan.some(b => b.ok), versi: 2, tahun: +tahun, sumber: 'CONTROL DASHBOARD Target Control', bulan, gagal: bulan.filter(b => !b.ok).map(b => b.bulan + ': ' + b.error), generated_at: sekarang };
}
if (typeof module !== 'undefined') module.exports = { susun };
if (typeof $ === 'function') {
  const items = $input.all().map(it => it.json);
  if (!items.length || (items.length === 1 && items[0].kosong)) { const th = items[0] ? items[0].tahun : ''; return [{ json: { ok: false, versi: 2, tahun: +th, message: 'Belum ada file Target Control untuk tahun ' + th + ' (isi daftar di node Daftar File)', bulan: [] } }]; }
  items.sort((a, b) => String(a.bulan).localeCompare(String(b.bulan)));
  const out = susun(items, items.map(x => x.error ? { error: x.error } : x.rows), items[0].tahun, DateTime.now().setZone('Asia/Makassar').toISO({ suppressMilliseconds: true }));
  out.versi = 2; return [{ json: out }];
}
